/**
 * 규칙 = [정규식, 치환]. 치환이 문자열이면 `$1`~`$9` 캡처가 **번역기를 한 번 더 통과**한다
 * (I18n.applyTemplate) — 캡처 안의 어종·아이템·슬롯·지명이 원문으로 남던 119차 버그 수정.
 * 함수형 치환은 두 번째 인자 `tr`로 직접 재번역한다.
 */
type Rule = [RegExp, string | ((m: RegExpExecArray, tr: (s: string) => string) => string)];

